//! Verify a saved INITIAL deployment without proving it again or using RPC.
use anyhow::{ensure,Result};use std::{env,fs,io::Write,path::Path};use sha2::{Digest,Sha256};use plonky2::field::goldilocks_field::GoldilocksField as F;use psy_client_common::data::qhashout::QHashOut;use psy_provider::request::QDeployContractRPCRequest;use psy_template_u124_markets::layout_preflight;
fn main()->Result<()>{let a=env::args().collect::<Vec<_>>();ensure!(a.len()==5,"ARTIFACT SAVED_INITIAL_REQUEST EXPECTED_DEPLOYER FRESH_REPORT");let artifact_bytes=fs::read(&a[1])?;let request_bytes=fs::read(&a[2])?;let artifact=serde_json::from_slice(&artifact_bytes)?;let request:QDeployContractRPCRequest<F>=serde_json::from_slice(&request_bytes)?;let deployer:QHashOut<F>=a[3].parse().map_err(|_|anyhow::anyhow!("invalid expected deployer"))?;let mut report=layout_preflight::verify_initial(&artifact,&request.deploy_contract,deployer)?;report["artifactSha256"]=serde_json::json!(format!("{:x}",Sha256::digest(&artifact_bytes)));report["requestSha256"]=serde_json::json!(format!("{:x}",Sha256::digest(&request_bytes)));report["reproved"]=serde_json::json!(false);report["broadcast"]=serde_json::json!(false);let p=Path::new(&a[4]);let mut out=fs::OpenOptions::new().write(true).create_new(true).open(p)?;out.write_all(&serde_json::to_vec_pretty(&report)?)?;out.sync_all()?;Ok(())}
